-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
-- P99 requires only the three dropped items; worn talisman and Kardakor quest flags are post-Velious prerequisites and deliberately excluded.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("I require some rare treasures to continue my studies.")
  elseif e.message:findi("rare treasures") then
    e.self:Say("There are 3 items that I seek to continue my studies of some various and musterious magics. Bring to me the teachings of a high ranking Kromzek that I hear goes by the name of Gkrean, a chipped fang from a beast deep within the Cursed Necropolis. Also for good measure, I require the Head of a Kromzek Staff Sergeant to prove to your dedication to our cause. Present these 3 items to me  and I shall do my best to identify its origin for you.")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 1864, item2 = 1865, item3 = 1863 }) then
    e.self:Say("I had faith I would see you again. Your dedication to aiding me in my studies is quite noteworthy. As I promised I would earlier, I have identified this talisman; it belonged once to Faliana. You may have heard of Faliana before, for she was the mate of Ralgyn, a well respected wurm noble of our Lord Yelinak. However it was last carried by Glanitar, the son of Ralgyn, who we have not seen for some time. To see this weathered trinket, I fear the worst for young Glanitar, however, his father must know that this was found. Please take this to him and, again, I thank you for your assistance in our time of need.")
    e.other:SummonItem(1866)
    e.other:Faction(436, 12, 0)
    e.other:Faction(430, 50, 0)
    e.other:Faction(448, -24, 0)
    e.other:AddEXP(100000)
    eq.depop_with_timer()
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
